#!/usr/bin/env bash
set -euo pipefail

echo "Aplicando Fase 8S: rediseno del panel de Inicio..."

if [ ! -d "backend" ] || [ ! -d "frontend" ]; then
  echo "Este script debe ejecutarse desde la raiz del repositorio (tms-production)." >&2
  exit 1
fi

mkdir -p "$(dirname "backend/src/modules/dashboard/dashboard.routes.ts")"
echo "  -> backend/src/modules/dashboard/dashboard.routes.ts"
echo  | base64 -d > "backend/src/modules/dashboard/dashboard.routes.ts"

mkdir -p "$(dirname "frontend/src/components/StatusBadge.tsx")"
echo "  -> frontend/src/components/StatusBadge.tsx"
echo  | base64 -d > "frontend/src/components/StatusBadge.tsx"

mkdir -p "$(dirname "frontend/src/pages/DashboardPage.tsx")"
echo "  -> frontend/src/pages/DashboardPage.tsx"
echo  | base64 -d > "frontend/src/pages/DashboardPage.tsx"

echo ""
echo "Listo. Cambios aplicados:"
echo "  - backend/src/modules/dashboard/dashboard.routes.ts (nuevo GET /dashboard/home)"
echo "  - frontend/src/components/StatusBadge.tsx"
echo "  - frontend/src/pages/DashboardPage.tsx (Inicio rediseñado)"
echo ""
echo "Esta fase NO toca el esquema de base de datos -- no hace falta prisma db push."
echo "Siguiente paso: revisa los cambios en GitHub Desktop y haz commit + push."
